import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<String> words = List.of("java", "sql", "java", "api", "java");
        Map<String, Integer> freq = new TreeMap<>();
        for (String w : words) freq.merge(w, 1, Integer::sum);
        for (Map.Entry<String, Integer> e : freq.entrySet()) {
            System.out.println(e.getKey() + "=" + e.getValue());
        }
        System.out.println(freq.containsKey("sql"));
    }
}

import java.util.*;

public class Main {
    record Employee(String name, int salary) implements Comparable<Employee> {
        @Override public int compareTo(Employee other) {
            return Integer.compare(salary, other.salary);
        }
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(List.of(
            new Employee("Aman", 40000), new Employee("Priya", 55000), new Employee("Ravi", 40000)));
        Collections.sort(staff);
        System.out.println(staff.get(0).name());
        staff.sort(Comparator.comparingInt(Employee::salary).reversed().thenComparing(Employee::name));
        System.out.println(staff.get(0).name() + " " + staff.get(0).salary());
    }
}

